-- seed.sql: plant protection products. Generated by data/crop_protection/build_seed.py
-- from protection_products.csv; change the CSV and build again. Safe to run more than once.
-- Needs 20261102_crop_protection_costs.sql first.

begin;

on conflict (name) do update set
  brand = excluded.brand,
  product_type = excluded.product_type,
  formulation = excluded.formulation,
  unit = excluded.unit,
  active_substances = excluded.active_substances,
  authorisation_no = excluded.authorisation_no,
  active = excluded.active,
  source = excluded.source;

commit;

-- Verification: select count(*) from public.protection_products;   -- at least 24
